export default {
  id: "biotech",
  code: "TB504",
  bar: "var(--c-biotech)",
  tint: "var(--c-biotech-bg)",
  nameTR: "Toprak Biyoteknolojisi",
  nameEN: "Soil Biotechnology",
  topics: [
    { id: "fundamentals", name: "Temel Kavramlar" },
    { id: "plant-microbe", name: "Bitki-Mikrop Etkileşimleri" },
    { id: "applications", name: "Uygulamalar" },
    { id: "methods", name: "Yöntemler" }
  ],
  cards: [
    // --- fundamentals ---
    { id:"microbiome", topic:"fundamentals", tr:"Toprak Mikrobiyomu", en:"Soil microbiome", def:"Topraktaki bakteri, mantar ve arke gibi mikroorganizmaların ve genetik materyallerinin oluşturduğu bütün topluluk.", defEn:"The collective community of microorganisms — bacteria, fungi, archaea — and their genetic material in soil." },
    { id:"soil-microbial-diversity", topic:"fundamentals", tr:"Toprak Mikrobiyal Çeşitliliği", en:"Soil microbial diversity", def:"Bir toprak örneğinde bulunan mikroorganizma türlerinin sayısı ve göreli bolluğu; genellikle toprak sağlığı ve ekosistem işlevinin bir göstergesi olarak kabul edilir.", defEn:"The number and relative abundance of microbial species present in a soil sample; often considered an indicator of soil health and ecosystem function." },
    { id:"bacteria-vs-archaea", topic:"fundamentals", tr:"Bakteri ve Arke Ayrımı", en:"Bacteria vs. archaea", def:"İkisi de prokaryot olmakla birlikte, hücre zarı yapısı ve genetik makineleri bakımından birbirinden köklü biçimde farklı olan, ayrı iki mikrobiyal alan (domain).", defEn:"Though both are prokaryotes, bacteria and archaea are two fundamentally distinct domains of life, differing in cell membrane chemistry and genetic machinery." },
    { id:"fungal-hyphae", topic:"fundamentals", tr:"Mantar Hifleri", en:"Fungal hyphae", def:"Mantarların iplik benzeri, dallanan yapıları; toprakta geniş bir ağ oluşturarak besin ve su taşınmasında ve agregat oluşumunda rol oynar.", defEn:"The thread-like, branching structures of fungi; they form an extensive network in soil, playing a role in nutrient/water transport and aggregate formation." },
    { id:"actinomycetes", topic:"fundamentals", tr:"Aktinomisetler", en:"Actinomycetes", def:"Mantarlara benzer iplik yapıları oluşturabilen, toprağa karakteristik 'toprak kokusunu' (geosmin) veren ve birçok antibiyotiğin doğal kaynağı olan bir bakteri grubu.", defEn:"A bacterial group capable of forming fungus-like filaments, responsible for soil's characteristic earthy smell (geosmin), and the natural source of many antibiotics." },
    { id:"soil-viruses-phages", topic:"fundamentals", tr:"Toprak Virüsleri (Bakteriyofajlar)", en:"Soil viruses (bacteriophages)", def:"Bakterileri enfekte edip parçalayan virüsler; bakteri popülasyonlarını düzenleyerek ve hücre içeriğini serbest bırakarak besin döngüsünü dolaylı olarak etkiler.", defEn:"Viruses that infect and lyse bacteria; they indirectly influence nutrient cycling by regulating bacterial populations and releasing cell contents." },
    { id:"biofilm", topic:"fundamentals", tr:"Biyofilm", en:"Biofilm", def:"Mikroorganizmaların bir yüzeye (örn. kök yüzeyi, toprak parçacığı) yapışarak oluşturdukları, kendi ürettikleri yapışkan bir matriksle korunan topluluk yapısı.", defEn:"A community structure formed when microorganisms attach to a surface (e.g. a root, a soil particle), protected by a sticky matrix they produce themselves." },
    { id:"microbial-hotspots", topic:"fundamentals", tr:"Mikrobiyal Sıcak Noktalar", en:"Microbial hotspots", def:"Rizosfer gibi, besin ve enerji kaynaklarının yoğunlaşması nedeniyle mikrobiyal aktivitenin toprağın geri kalanına göre çok daha yoğun olduğu bölgeler.", defEn:"Zones like the rhizosphere where microbial activity is far more concentrated than in the rest of the soil, due to a local concentration of nutrient and energy sources." },
    { id:"copiotrophs-oligotrophs", topic:"fundamentals", tr:"Kopyotrof ve Oligotrof Mikroorganizmalar", en:"Copiotrophs and oligotrophs", def:"Kopyotroflar besince zengin ortamlarda hızlı büyüyen fırsatçı organizmalardır; oligotroflar ise besince fakir ortamlarda yavaş ama istikrarlı büyüyen organizmalardır.", defEn:"Copiotrophs are opportunistic organisms that grow fast in nutrient-rich conditions; oligotrophs grow slowly but steadily in nutrient-poor conditions." },
    { id:"soil-microbial-biomass-c", topic:"fundamentals", tr:"Toprak Mikrobiyal Biyokütle Karbonu", en:"Soil microbial biomass carbon (SMB-C)", def:"Topraktaki canlı mikrobiyal biyokütlenin karbon içeriğinin ölçülmesi; toprağın biyolojik olarak aktif havuzunun büyüklüğünü nicel olarak gösterir.", defEn:"A measurement of the carbon content of living microbial biomass in soil; it quantifies the size of the soil's biologically active pool." },

    // --- plant-microbe ---
    { id:"rhizosphere", topic:"plant-microbe", tr:"Rizosfer", en:"Rhizosphere", def:"Kök salgılarının ve bunların çektiği mikrobiyal aktivitenin doğrudan etkilediği dar toprak bölgesi.", defEn:"The narrow zone of soil directly influenced by root secretions and the microbial activity they attract." },
    { id:"pgpr", topic:"plant-microbe", tr:"Bitki Büyümesini Teşvik Eden Rizobakteriler (PGPR)", en:"Plant growth-promoting rhizobacteria", def:"Besin çözünürleştirme, hormon üretimi veya patojen baskılama yoluyla bitki gelişimini destekleyen, köklerle ilişkili bakteriler.", defEn:"Root-associated bacteria that boost plant growth via nutrient solubilization, hormone production, or pathogen suppression." },
    { id:"mycorrhiza", topic:"plant-microbe", tr:"Mikoriza", en:"Mycorrhiza", def:"Mantarlar ile bitki kökleri arasında su ve besin alımını artıran, karşılıklı yarar sağlayan bir simbiyoz.", defEn:"A mutually beneficial symbiosis between fungi and plant roots that improves water and nutrient uptake." },
    { id:"nitrogen-fixation", topic:"plant-microbe", tr:"Azot Fiksasyonu", en:"Nitrogen fixation", def:"Atmosferik N₂'nin, örneğin baklagil nodüllerindeki Rhizobium tarafından, bitkinin kullanabileceği formlara biyolojik olarak dönüştürülmesi.", defEn:"Biological conversion of atmospheric N₂ into plant-usable forms, e.g. by Rhizobium in legume nodules." },
    { id:"arbuscular-mycorrhiza", topic:"plant-microbe", tr:"Arbüsküler Mikoriza (AM)", en:"Arbuscular mycorrhiza (AM)", def:"En yaygın mikoriza türü; mantar hifleri kök hücrelerinin içine girerek besin değişimi için ağaç dalı benzeri (arbüsküler) yapılar oluşturur.", defEn:"The most common type of mycorrhiza; fungal hyphae penetrate root cells and form tree-branch-like (arbuscular) structures for nutrient exchange." },
    { id:"rhizobium-nodulation", topic:"plant-microbe", tr:"Rhizobium Nodülasyonu", en:"Rhizobium nodulation", def:"Baklagil kökleri ile Rhizobium bakterileri arasında kimyasal sinyal alışverişiyle başlayan, kökte azot fiksasyonu yapan nodüllerin oluşmasıyla sonuçlanan simbiyotik süreç.", defEn:"The symbiotic process, beginning with chemical signal exchange between legume roots and Rhizobium bacteria, that results in the formation of nitrogen-fixing root nodules." },
    { id:"endophytes", topic:"plant-microbe", tr:"Endofitler", en:"Endophytes", def:"Görünür bir hastalık belirtisi oluşturmadan, bitki dokularının içinde (rizosferin dışında, doğrudan doku içinde) yaşayan mikroorganizmalar.", defEn:"Microorganisms that live inside plant tissues — not just in the rhizosphere, but within the tissue itself — without causing visible disease." },
    { id:"root-exudates", topic:"plant-microbe", tr:"Kök Salgıları", en:"Root exudates", def:"Bitki köklerinin toprağa saldığı şekerler, organik asitler ve amino asitler gibi bileşikler; rizosferdeki mikrobiyal topluluğu besler ve şekillendirir.", defEn:"Compounds like sugars, organic acids, and amino acids released by plant roots into the soil; they feed and shape the microbial community in the rhizosphere." },
    { id:"siderophores", topic:"plant-microbe", tr:"Siderofor", en:"Siderophores", def:"Bazı PGPR ve mantarların ürettiği, demiri (Fe³⁺) toprakta yüksek afiniteyle bağlayan küçük moleküller; hem mikrobun kendi demir alımını sağlar hem de patojenleri demirden mahrum bırakarak baskılayabilir.", defEn:"Small molecules produced by some PGPR and fungi that bind iron (Fe³⁺) in soil with high affinity; they secure the microbe's own iron supply and can suppress pathogens by starving them of iron." },
    { id:"induced-systemic-resistance", topic:"plant-microbe", tr:"İndüklenmiş Sistemik Direnç (ISR)", en:"Induced systemic resistance (ISR)", def:"Belirli PGPR'lerin kökle etkileşimi sonucu bitkinin bağışıklık sisteminin 'uyarılması'; bitki daha sonra karşılaştığı patojenlere karşı daha hızlı ve güçlü tepki verir.", defEn:"The 'priming' of a plant's immune system following interaction with certain PGPR at the root; the plant then responds faster and more strongly to pathogens it later encounters." },
    { id:"quorum-sensing", topic:"plant-microbe", tr:"Kuorum Algılama (Quorum Sensing)", en:"Quorum sensing", def:"Bakterilerin, popülasyon yoğunluğunu sinyal moleküllerinin konsantrasyonu üzerinden algılayıp, belirli bir eşiğe ulaşıldığında davranışlarını (örn. biyofilm oluşumu) topluca koordine etmesi.", defEn:"Bacteria sensing population density through the concentration of signaling molecules, and coordinating collective behavior (e.g. biofilm formation) once a threshold is reached." },

    // --- applications ---
    { id:"biofertilizer", topic:"applications", tr:"Biyogübre", en:"Biofertilizer", def:"Bitkiye besin yarayışlılığını artıran canlı mikroorganizmalar içeren bir ürün.", defEn:"A product containing living microorganisms that enhance nutrient availability to plants." },
    { id:"bioremediation", topic:"applications", tr:"Biyoremediasyon", en:"Bioremediation", def:"Toprak veya sudaki kirleticileri parçalamak ya da zararsız hale getirmek için mikroorganizmaların kullanılması.", defEn:"Using microorganisms to degrade or detoxify contaminants in soil or water." },
    { id:"biocontrol-agent", topic:"applications", tr:"Biyolojik Mücadele Ajanı", en:"Biocontrol agent", def:"Bitki patojenlerini veya zararlıları baskılamak için uygulanan yararlı bir organizma.", defEn:"A beneficial organism applied to suppress plant pathogens or pests." },
    { id:"phytoremediation", topic:"applications", tr:"Fitoremediasyon", en:"Phytoremediation", def:"Kirletici maddeleri topraktan uzaklaştırmak, parçalamak veya sabitlemek için bitkilerin (genellikle kök mikrobiyomlarıyla birlikte) kullanılması.", defEn:"The use of plants (often together with their root microbiome) to remove, degrade, or stabilize contaminants from soil." },
    { id:"mycoremediation", topic:"applications", tr:"Mikoremediasyon", en:"Mycoremediation", def:"Mantarların, özellikle güçlü enzim sistemleri sayesinde, kirleticileri (örn. petrol türevleri) parçalamak için kullanıldığı bir biyoremediasyon türü.", defEn:"A form of bioremediation that uses fungi, particularly for their powerful enzyme systems, to break down contaminants like petroleum derivatives." },
    { id:"biopesticide", topic:"applications", tr:"Biyopestisit", en:"Biopesticide", def:"Bir biyolojik mücadele organizmasından veya onun ürettiği bileşiklerden elde edilen, zararlı veya hastalık etmenlerini kontrol etmek için formüle edilmiş ticari ürün.", defEn:"A commercial product formulated from a biocontrol organism or its compounds, used to control pests or disease agents." },
    { id:"biostimulant", topic:"applications", tr:"Biyostimülant", en:"Biostimulant", def:"Doğrudan besin sağlamak yerine, bitkinin besin alımını, stres toleransını veya genel gelişimini teşvik eden mikrobiyal veya biyolojik kökenli bir ürün.", defEn:"A microbial or biologically derived product that promotes a plant's nutrient uptake, stress tolerance, or overall development, rather than directly supplying nutrients." },
    { id:"microbial-inoculant", topic:"applications", tr:"Mikrobiyal Aşı (İnokülant)", en:"Microbial inoculant", def:"Faydalı mikroorganizmaların (örn. Rhizobium, mikorizal mantar) canlı kültürünün, toprağa veya tohuma uygulanmak üzere formüle edilmiş hali.", defEn:"A formulated live culture of beneficial microorganisms (e.g. Rhizobium, mycorrhizal fungi) prepared for application to soil or seed." },
    { id:"compost-tea", topic:"applications", tr:"Kompost Çayı", en:"Compost tea", def:"Olgun kompostun suda bekletilmesi (bazen havalandırılarak) yoluyla elde edilen, faydalı mikroorganizmaları ve çözünür besinleri içeren sıvı bir uygulama.", defEn:"A liquid preparation, obtained by steeping (sometimes aerating) mature compost in water, containing beneficial microorganisms and soluble nutrients." },
    { id:"biological-soil-health-indicators", topic:"applications", tr:"Biyolojik Toprak Sağlığı Göstergeleri", en:"Biological soil health indicators", def:"Mikrobiyal biyokütle, solunum ve enzim aktivitesi gibi ölçütlerin, yalnızca kimyasal/fiziksel testlerin yakalayamadığı toprak sağlığı boyutlarını değerlendirmek için kullanılması.", defEn:"Using measures like microbial biomass, respiration, and enzyme activity to assess dimensions of soil health that chemical/physical tests alone can't capture." },

    // --- methods ---
    { id:"metagenomics", topic:"methods", tr:"Metagenomik", en:"Metagenomics", def:"Doğrudan çevresel bir örnekten elde edilen genetik materyalin incelenmesi; mikrobiyal toplulukların tamamını kültüre almadan yakalar.", defEn:"Studying genetic material recovered directly from an environmental sample, capturing whole microbial communities without culturing them." },
    { id:"rrna-sequencing", topic:"methods", tr:"16S rRNA Dizileme", en:"16S rRNA sequencing", def:"Bir örnekteki taksonları tanımlamak ve sınıflandırmak için korunmuş bir bakteri genini okuyan moleküler yöntem.", defEn:"A molecular method that reads a conserved bacterial gene to identify and classify taxa in a sample." },
    { id:"enzyme-activity", topic:"methods", tr:"Toprak Enzim Aktivitesi", en:"Soil enzyme activity", def:"Toprakta mikrobiyal topluluğun süregelen işlevsel ve biyokimyasal aktivitesinin ölçüsü.", defEn:"A measure of the microbial community's ongoing functional and biochemical activity in soil." },
    { id:"culture-independent", topic:"methods", tr:"Kültürden Bağımsız Yöntemler", en:"Culture-independent methods", def:"Mikropları laboratuvarda üretmeye gerek kalmadan doğrudan örnekten inceleyen moleküler teknikler.", defEn:"Molecular techniques that study microbes directly from a sample, without needing to grow them in the lab." },
    { id:"pcr", topic:"methods", tr:"PCR (Polimeraz Zincir Reaksiyonu)", en:"PCR (Polymerase Chain Reaction)", def:"Belirli bir DNA dizisinin laboratuvarda milyonlarca kopyasının üretildiği temel moleküler biyoloji tekniği; birçok toprak mikrobiyolojisi yönteminin temelini oluşturur.", defEn:"The foundational molecular biology technique that makes millions of copies of a specific DNA sequence in the lab; it underlies many soil microbiology methods." },
    { id:"fish-technique", topic:"methods", tr:"FISH (Floresan İn Situ Hibridizasyon)", en:"FISH (Fluorescence In Situ Hybridization)", def:"Floresan işaretli DNA problarının, belirli mikroorganizma gruplarını örnek içinde yerinde (in situ) görselleştirmesini sağlayan bir teknik.", defEn:"A technique using fluorescently labeled DNA probes to visualize specific groups of microorganisms directly within a sample (in situ)." },
    { id:"plfa-analysis", topic:"methods", tr:"PLFA Analizi (Fosfolipit Yağ Asidi Analizi)", en:"PLFA analysis (Phospholipid Fatty Acid analysis)", def:"Canlı hücre zarlarına özgü yağ asitlerinin analiz edilmesiyle, bir toprak örneğindeki mikrobiyal topluluğun genel yapısının (bakteri/mantar oranı gibi) belirlenmesi.", defEn:"Analyzing fatty acids specific to living cell membranes to determine the overall structure of a soil sample's microbial community, such as the bacteria-to-fungi ratio." },
    { id:"metatranscriptomics", topic:"methods", tr:"Metatranskriptomik", en:"Metatranscriptomics", def:"Bir örnekteki mikrobiyal topluluğun o anda hangi genleri aktif olarak ifade ettiğini (RNA üzerinden) inceleyen yöntem; metagenomikten farklı olarak yalnızca 'kimin var olduğunu' değil 'kimin ne yaptığını' gösterir.", defEn:"A method examining which genes a microbial community is actively expressing (via RNA) at a given moment; unlike metagenomics, it shows not just who is present but who is actively doing what." },
    { id:"qpcr", topic:"methods", tr:"qPCR (Kantitatif PCR)", en:"qPCR (quantitative PCR)", def:"Standart PCR'ın, hedef bir DNA dizisinin örnekteki başlangıç miktarını da ölçmeye olanak tanıyan bir uzantısı; belirli bir mikroorganizma grubunun bolluğunu nicelleştirmek için kullanılır.", defEn:"An extension of standard PCR that also measures the starting quantity of a target DNA sequence in a sample; used to quantify the abundance of a specific microbial group." },
    { id:"most-probable-number", topic:"methods", tr:"En Muhtemel Sayı Yöntemi (EMS)", en:"Most Probable Number (MPN) method", def:"Ardışık seyreltmeler ve büyüme gözlemine dayanan, belirli bir mikroorganizma grubunun örnekteki yoğunluğunu istatistiksel olarak tahmin eden, kültüre dayalı klasik bir yöntem.", defEn:"A classic culture-based method that statistically estimates the density of a specific microbial group in a sample, based on serial dilutions and observed growth." },
    { id:"dgge", topic:"methods", tr:"DGGE (Denatüre Edici Gradyan Jel Elektroforezi)", en:"DGGE (Denaturing Gradient Gel Electrophoresis)", def:"PCR ile çoğaltılmış DNA parçalarını dizi farklılıklarına göre ayırarak, bir mikrobiyal topluluğun genel 'parmak izini' görselleştiren, sekanslamadan önce yaygın kullanılan bir teknik.", defEn:"A technique that separates PCR-amplified DNA fragments based on sequence differences, visualizing a microbial community's overall 'fingerprint' — widely used before sequencing became common." }
  ],
  quiz: [
    // --- fundamentals (15) ---
    { id:"q-diversity-ecosystem-function", topic:"fundamentals", q:"Toprak mikrobiyal çeşitliliği neden ekosistem işlevinin bir göstergesi olarak kabul edilir?", qEn:"Why is soil microbial diversity considered an indicator of ecosystem function?", opts:["Çeşitlilikle işlev arasında hiçbir bağlantı yoktur","Yüksek çeşitlilik, farklı işlevsel rollerin (ayrıştırma, besin döngüsü, patojen baskılama) daha güvenilir şekilde yerine getirilmesini sağlayabilir","Çeşitlilik yalnızca görsel bir özelliktir","Düşük çeşitlilik her zaman daha iyidir"], a:1, ex:"Fonksiyonel yedeklilik sağlayan çeşitli bir topluluk, bir tür kaybolsa bile ekosistem işlevlerinin (örn. ayrışma) sürmesini sağlayabilir.", exEn:"A diverse community with functional redundancy can keep ecosystem functions (e.g. decomposition) running even if one species is lost." },
    { id:"q-bacteria-archaea-diff", topic:"fundamentals", q:"Bakteri ve arke arasındaki temel fark nedir?", qEn:"What is the key difference between bacteria and archaea?", opts:["İkisi aynı organizma grubudur","İkisi de prokaryottur ama hücre zarı kimyası ve genetik makineleri bakımından ayrı domainlerdir","Arkeler yalnızca hayvanlarda bulunur","Bakteriler yalnızca toprakta, arkeler yalnızca suda bulunur"], a:1, ex:"Bakteri ve arke, morfolojik olarak benzer görünseler de, hücre zarı lipidleri ve transkripsiyon makineleri gibi temel özellikler bakımından birbirinden köklü biçimde ayrılır.", exEn:"Though bacteria and archaea look morphologically similar, they differ fundamentally in core features like cell membrane lipids and transcription machinery." },
    { id:"q-fungal-hyphae-function", topic:"fundamentals", q:"Mantar hiflerinin toprak ekosistemindeki işlevi nedir?", qEn:"What is the function of fungal hyphae in the soil ecosystem?", opts:["Hiçbir işlevi yoktur","Geniş bir ağ oluşturarak besin/su taşınmasına ve agregat oluşumuna katkıda bulunur","Yalnızca toprağı zehirler","Yalnızca yüzeyde kalır, toprağa nüfuz etmez"], a:1, ex:"Hif ağları, toprak parçacıkları arasında uzun mesafeler kat ederek hem besin/su taşınmasını hem de fiziksel olarak agregatları bir arada tutmayı sağlar.", exEn:"Hyphal networks span long distances between soil particles, both transporting nutrients/water and physically holding aggregates together." },
    { id:"q-actinomycetes-traits", topic:"fundamentals", q:"Aktinomisetler hangi karakteristik özellikleriyle bilinir?", qEn:"What characteristic traits are actinomycetes known for?", opts:["Yalnızca patojenik olmalarıyla","Toprağın karakteristik kokusuna (geosmin) katkıda bulunmaları ve doğal antibiyotik kaynağı olmalarıyla","Yalnızca su altında yaşamalarıyla","Fotosentez yapmalarıyla"], a:1, ex:"Aktinomisetler, mantar benzeri iplik yapıları oluşturabilen bakterilerdir; birçok klinik antibiyotik (örn. streptomisin) aktinomisetlerden elde edilmiştir.", exEn:"Actinomycetes are bacteria capable of forming fungus-like filaments; many clinical antibiotics (e.g. streptomycin) were derived from them." },
    { id:"q-phages-nutrient-cycle", topic:"fundamentals", q:"Toprak virüsleri (bakteriyofajlar) besin döngüsünü nasıl dolaylı olarak etkiler?", qEn:"How do soil viruses (bacteriophages) indirectly affect the nutrient cycle?", opts:["Hiçbir etkileri yoktur","Bakteri hücrelerini parçalayarak (lize ederek) hücre içeriğini toprağa serbest bırakırlar","Yalnızca bitkileri enfekte ederler","Besin döngüsüyle hiçbir ilgileri yoktur"], a:1, ex:"Bir bakteriyofaj bir bakteriyi parçaladığında, bakterinin hücre içindeki besin elementleri (karbon, azot) toprağa salınarak döngüye tekrar girer.", exEn:"When a bacteriophage lyses a bacterium, the nutrients (carbon, nitrogen) inside that cell are released into the soil and re-enter the cycle." },
    { id:"q-biofilm-advantage", topic:"fundamentals", q:"Biyofilm oluşumu mikroorganizmalara ne gibi bir avantaj sağlar?", qEn:"What advantage does biofilm formation give microorganisms?", opts:["Hiçbir avantaj sağlamaz","Kendi ürettikleri koruyucu bir matriks içinde, çevresel streslere ve rekabete karşı daha dayanıklı bir topluluk oluştururlar","Biyofilm mikroorganizmaları zayıflatır","Yalnızca hastalık etmenleri biyofilm oluşturur"], a:1, ex:"Biyofilm matriksi, içindeki mikroorganizmaları kuruma, antimikrobiyal maddeler ve rekabetten koruyarak hayatta kalma şanslarını artırır.", exEn:"The biofilm matrix protects the microorganisms within it from desiccation, antimicrobials, and competition, improving their odds of survival." },
    { id:"q-microbial-hotspots-def", topic:"fundamentals", q:"Mikrobiyal sıcak noktalar kavramı neyi ifade eder?", qEn:"What does the concept of microbial hotspots refer to?", opts:["Toprağın en sıcak bölgelerini","Besin ve enerji kaynaklarının yoğunlaşması nedeniyle mikrobiyal aktivitenin çok daha yoğun olduğu bölgeleri (örn. rizosfer)","Yalnızca çöl topraklarını","Mikrobiyal aktivitenin hiç olmadığı bölgeleri"], a:1, ex:"Rizosfer gibi bölgeler, kök salgılarının sağladığı bol enerji kaynağı nedeniyle, toprağın geri kalanına göre çok daha yüksek mikrobiyal aktivite gösterir.", exEn:"Zones like the rhizosphere show far higher microbial activity than the rest of the soil, thanks to the abundant energy supply from root exudates." },
    { id:"q-copiotroph-oligotroph-diff", topic:"fundamentals", q:"Kopyotrof mikroorganizmalar ile oligotrof mikroorganizmalar arasındaki fark nedir?", qEn:"What is the difference between copiotrophic and oligotrophic microorganisms?", opts:["Aynı büyüme stratejisine sahiptirler","Kopyotroflar besince zengin ortamlarda hızlı büyüyen fırsatçılardır; oligotroflar besince fakir ortamlarda yavaş ama istikrarlı büyür","Oligotroflar her zaman daha hızlı büyür","Kopyotroflar yalnızca besince fakir ortamlarda yaşar"], a:1, ex:"Bu iki strateji, r-K seçilimi ekolojik kavramına benzer — kopyotroflar hızlı fırsatçı büyümeyi, oligotroflar verimliliği ve dayanıklılığı önceliklendirir.", exEn:"These two strategies parallel the ecological concept of r-K selection — copiotrophs prioritize fast opportunistic growth, oligotrophs prioritize efficiency and resilience." },
    { id:"q-smb-c-meaning", topic:"fundamentals", q:"Toprak mikrobiyal biyokütle karbonu (SMB-C) ölçümü neyi gösterir?", qEn:"What does measuring soil microbial biomass carbon (SMB-C) show?", opts:["Toprağın toplam karbon içeriğini","Topraktaki canlı mikrobiyal biyokütlenin karbon içeriğini, yani biyolojik olarak aktif havuzun büyüklüğünü","Yalnızca bitki köklerindeki karbonu","Atmosferdeki karbon miktarını"], a:1, ex:"SMB-C, toprağın toplam organik karbonundan farklı olarak, spesifik olarak canlı mikrobiyal topluluğun bünyesindeki karbonu ölçer.", exEn:"Unlike total soil organic carbon, SMB-C specifically measures the carbon held within the living microbial community." },
    { id:"q-archaea-extreme-environments", topic:"fundamentals", q:"Arkeler hangi tür ortamlarla özellikle ilişkilendirilir?", qEn:"What kind of environments are archaea especially associated with?", opts:["Yalnızca ılıman, nötr pH'lı topraklarla","Genellikle ekstrem koşullarla (yüksek tuzluluk, sıcaklık) ilişkilendirilirler, ancak sıradan topraklarda da (örn. nitrifikasyonda) önemli rol oynarlar","Arkeler yalnızca insan bağırsağında bulunur","Arkeler toprakta hiç bulunmaz"], a:1, ex:"Arkeler tarihsel olarak ekstrem ortamlarla (ekstremofiller) ilişkilendirilse de, amonyak oksitleyen arkeler gibi gruplar sıradan tarım topraklarında da nitrifikasyona önemli katkı sağlar.", exEn:"Although archaea have historically been associated with extreme environments (extremophiles), groups like ammonia-oxidizing archaea also contribute significantly to nitrification in ordinary farmland." },
    { id:"q-hyphae-glomalin-link", topic:"fundamentals", q:"Mantar hiflerinin toprak agregat oluşumuna katkısı, organik madde yönetiminde öğrenilen glomalin kavramıyla nasıl ilişkilidir?", qEn:"How does fungal hyphae's contribution to soil aggregate formation relate to the concept of glomalin from organic matter management?", opts:["Hiçbir ilişkisi yoktur","Mikorizal hifler, agregatları fiziksel olarak sarmasının yanı sıra glomalin gibi yapışkan bileşikler de üreterek agregat stabilitesine çift yönlü katkı sağlar","Hifler yalnızca agregatları parçalar","Glomalin yalnızca bakteriler tarafından üretilir"], a:1, ex:"Hifler hem fiziksel olarak toprak parçacıklarını sarıp bir arada tutar hem de glomalin gibi yapışkan maddeler salgılayarak kimyasal olarak da agregatlaşmaya katkıda bulunur.", exEn:"Hyphae contribute to aggregation in two ways — physically wrapping around and binding soil particles, and chemically, by secreting sticky substances like glomalin." },
    { id:"q-biofilm-rhizosphere-prevalence", topic:"fundamentals", q:"Biyofilm oluşumu rizosferde neden özellikle yaygındır?", qEn:"Why is biofilm formation especially common in the rhizosphere?", opts:["Rizosferde hiç biyofilm oluşmaz","Kök yüzeyi, mikroorganizmaların tutunabileceği bir yüzey ve kök salgıları yoluyla bol besin sağlar","Rizosferde besin bulunmaz","Yalnızca patojenler rizosferde biyofilm oluşturur"], a:1, ex:"Kök yüzeyi, tutunma için bir zemin ve kök salgıları yoluyla sürekli bir besin kaynağı sunduğundan, biyofilm oluşumu için ideal bir ortamdır.", exEn:"The root surface offers both a substrate to attach to and a steady nutrient supply via exudates, making it an ideal environment for biofilm formation." },
    { id:"q-phage-bacteria-ratio", topic:"fundamentals", q:"Toprakta bakteriyofaj sayısının bakteri sayısına oranı hakkında genel bir gözlem nedir?", qEn:"What is a general observation about the ratio of bacteriophages to bacteria in soil?", opts:["Bakteriyofajlar bakterilerden çok daha azdır","Birçok ortamda bakteriyofajlar bakterilerden sayıca daha fazla olabilir","Bakteriyofaj hiçbir zaman bakteriden fazla olamaz","Bu oran hiçbir zaman ölçülememiştir"], a:1, ex:"Birçok ekosistemde (topraklar dahil) viral parçacıklar, konakçı bakteri hücrelerinden sayıca daha fazla olabilir; bu da onların ekolojik etkisinin önemini gösterir.", exEn:"In many ecosystems, including soils, viral particles can outnumber their host bacterial cells — underscoring their ecological significance." },
    { id:"q-copiotroph-disturbance-response", topic:"fundamentals", q:"Toprak işleme gibi bir bozulma sonrası, kopyotrof organizmaların popülasyonunda tipik olarak ne gözlenir?", qEn:"What is typically observed in copiotroph populations after a disturbance like tillage?", opts:["Popülasyonları hemen çöker","Taze açığa çıkan organik maddeyle beslenerek hızla çoğalırlar","Hiçbir değişiklik olmaz","Yalnızca oligotroflar tepki verir"], a:1, ex:"Toprak işleme, önceden korunan organik maddeyi açığa çıkararak kopyotroflar için ani bir besin fazlası yaratır; bu da onların popülasyonunda hızlı bir artışa yol açar.", exEn:"Tillage exposes previously protected organic matter, creating a sudden nutrient surplus for copiotrophs, which triggers a rapid rise in their population." },
    { id:"q-healthy-microbiome-def", topic:"fundamentals", q:"Bir toprak mikrobiyomunun 'sağlıklı' kabul edilmesi genellikle neye dayanır?", qEn:"What does considering a soil microbiome 'healthy' generally rest on?", opts:["Yalnızca tek bir baskın türün varlığına","Çeşitliliğin, işlevsel dengenin ve zararlı organizmaları baskılayabilme kapasitesinin birlikte değerlendirilmesine","Toprakta hiç mikroorganizma bulunmamasına","Yalnızca toprağın rengine"], a:1, ex:"Sağlıklı bir mikrobiyom tek bir ölçütle değil, çeşitlilik, işlevsel kapasite ve dayanıklılığın bir arada değerlendirilmesiyle tanımlanır.", exEn:"A healthy microbiome isn't defined by a single metric, but by jointly assessing diversity, functional capacity, and resilience." },

    // --- plant-microbe (15) ---
    { id:"q-pgpr-function", topic:"plant-microbe", q:"PGPR'nin (bitki büyümesini teşvik eden rizobakteriler) temel işlevi nedir?", qEn:"What is the main function of PGPR (plant growth-promoting rhizobacteria)?", opts:["Her zaman bitkiler için patojeniktirler","Besin çözünürleştirme, fitohormon üretimi ve patojen baskılama gibi mekanizmalarla büyümeyi teşvik ederler","Yalnızca toprak pH'ını değiştirirler","Tüm organik maddeyi CO₂'ye dönüştürürler"], a:1, ex:"PGPR aynı anda birkaç tamamlayıcı mekanizma üzerinden etki eder; bu yüzden hem biyogübre hem de biyolojik mücadele ajanı olarak incelenirler.", exEn:"PGPR act through several complementary mechanisms at once, which is why they're studied as both biofertilizers and biocontrol agents." },
    { id:"q-mycorrhiza-relationship", topic:"plant-microbe", q:"Mikorizal ilişkideki tanımlayıcı özellik nedir?", qEn:"What is the defining relationship in a mycorrhizal association?", opts:["Bitkiye zarar veren parazitik bir ilişki","Su ve besin alımını artıran, mantar ile kökler arasında karşılıklı yararlı bir simbiyoz","Aynı kaynaklar için saf rekabet","Bitkiyle doğrudan bir etkileşim yok"], a:1, ex:"Mantar, bitkinin ürettiği şekerler karşılığında kökün su/besin alımı için etkili yüzey alanını genişletir.", exEn:"The fungus extends the root's effective surface area for water/nutrient uptake in exchange for plant-produced sugars." },
    { id:"q-n-fixation-benefit", topic:"plant-microbe", q:"Biyolojik azot fiksasyonu (örn. baklagil nodüllerindeki Rhizobium) toprak verimliliğine nasıl fayda sağlar?", qEn:"How does biological nitrogen fixation (e.g. Rhizobium in legume nodules) benefit soil fertility?", opts:["Ekosistemden azotu uzaklaştırır","Atmosferik N₂'yi bitkiye yarayışlı formlara dönüştürerek sentetik gübre ihtiyacını azaltır","Yalnızca güçlü asidik topraklarda işlev görür","Agronomik açıdan gerçek bir önemi yoktur"], a:1, ex:"Bu simbiyoz, önemli bir doğal azot girdisidir; bu yüzden baklagiller toprak verimliliğini artırmak için ürün rotasyonunda yaygın olarak kullanılır.", exEn:"This symbiosis is a major natural nitrogen input, which is why legumes are widely used in rotation to build soil fertility." },
    { id:"q-rhizosphere-def", topic:"plant-microbe", q:"Rizosfer nedir?", qEn:"What is the rhizosphere?", opts:["Köklerden etkilenmeyen en derin toprak katmanı","Kök salgılarının ve bunların yoğunlaştırdığı mikrobiyal aktivitenin doğrudan etkilediği toprak bölgesi","Kökten uzak, ana kütle toprağın eş anlamlısı","Mikrobiyal yoğunluğun artmadığı bir alan"], a:1, ex:"Kök salgıları (şekerler, organik asitler), kök çevresindeki mikrobiyal aktiviteyi besler ve yoğunlaştırır; bu da rizosferi bir mikrobiyal sıcak nokta haline getirir.", exEn:"Root exudates (sugars, organic acids) feed and concentrate microbial activity right around the root, making the rhizosphere a microbial hotspot." },
    { id:"q-am-structural-feature", topic:"plant-microbe", q:"Arbüsküler mikoriza (AM) diğer mikoriza türlerinden hangi yapısal özelliğiyle ayrılır?", qEn:"What structural feature distinguishes arbuscular mycorrhiza (AM) from other mycorrhiza types?", opts:["Kök yüzeyinde kalır, hiç içeri girmez","Hifleri kök hücrelerinin içine girerek ağaç dalı benzeri arbüsküler yapılar oluşturur","Yalnızca su altı bitkilerinde bulunur","Hiçbir bitkiyle ilişki kurmaz"], a:1, ex:"AM mantarları, hifleriyle kök hücre duvarını geçip hücre zarının içinde kalarak besin değişimi için geniş yüzeyli arbüsküler yapılar oluşturur — bu, bitki-mantar simbiyozunun en yaygın türüdür.", exEn:"AM fungi cross the root cell wall with their hyphae and, staying within the cell membrane, form high-surface-area arbuscular structures for nutrient exchange — the most common type of plant-fungus symbiosis." },
    { id:"q-rhizobium-nodulation-trigger", topic:"plant-microbe", q:"Rhizobium nodülasyonu hangi olayla başlar?", qEn:"What event triggers Rhizobium nodulation?", opts:["Rastgele bir toprak enfeksiyonuyla","Baklagil kökü ile Rhizobium arasındaki kimyasal sinyal (flavonoid-Nod faktörü) alışverişiyle","Yalnızca toprak işlemeyle","Kökün fiziksel olarak zarar görmesiyle"], a:1, ex:"Bitki kökü flavonoid bileşikleri salgılar, Rhizobium bunlara Nod faktörleriyle yanıt verir; bu moleküler diyalog nodül oluşumunu tetikler.", exEn:"The root releases flavonoid compounds, Rhizobium responds with Nod factors — this molecular dialogue triggers nodule formation." },
    { id:"q-endophyte-vs-rhizosphere", topic:"plant-microbe", q:"Endofitleri rizosfer mikroorganizmalarından ayıran temel özellik nedir?", qEn:"What is the key feature that distinguishes endophytes from rhizosphere microorganisms?", opts:["Endofitler topraktan tamamen bağımsızdır","Endofitler bitki dokusunun içinde yaşarken, rizosfer mikroorganizmaları kökün dışında, çevresindeki toprakta yaşar","Rizosfer mikroorganizmaları her zaman patojeniktir","Endofitler yalnızca hayvanlarda bulunur"], a:1, ex:"Rizosfer 'kök çevresi'ni ifade ederken, endofitik yaşam tarzı doğrudan bitki dokusunun içinde, görünür hastalık belirtisi oluşturmadan sürer.", exEn:"While the rhizosphere refers to the 'root zone' outside the plant, the endophytic lifestyle takes place directly inside plant tissue, without causing visible disease." },
    { id:"q-root-exudates-shaping", topic:"plant-microbe", q:"Kök salgıları rizosfer mikrobiyal topluluğunu nasıl şekillendirir?", qEn:"How do root exudates shape the rhizosphere microbial community?", opts:["Hiçbir etkisi yoktur","Şekerler, organik asitler gibi bileşikler salgılayarak belirli mikroorganizmaları besler ve çeker","Yalnızca mikroorganizmaları uzaklaştırır","Kökler hiçbir madde salgılamaz"], a:1, ex:"Bitki, kök salgılarının bileşimini değiştirerek rizosferdeki hangi mikroorganizma gruplarının zenginleşeceğini aktif olarak etkileyebilir.", exEn:"By varying the composition of its root exudates, a plant can actively influence which microbial groups become enriched in the rhizosphere." },
    { id:"q-siderophore-dual-role", topic:"plant-microbe", q:"Sideroforların hem mikrobiyal beslenme hem de biyolojik mücadelede ikili bir rolü olmasının nedeni nedir?", qEn:"Why do siderophores play a dual role in both microbial nutrition and biocontrol?", opts:["Sideroforların hiçbir işlevi yoktur","Demiri yüksek afiniteyle bağlayarak hem üreten mikrobun demir alımını sağlar hem de patojenleri demirden mahrum bırakabilir","Sideroforlar yalnızca azot bağlar","Sideroforlar yalnızca bitkiler tarafından üretilir"], a:1, ex:"Demir birçok mikroorganizma için sınırlayıcı bir kaynaktır; güçlü siderofor üreten PGPR, bu kaynağı tekelleştirerek dolaylı yoldan patojenleri baskılayabilir.", exEn:"Iron is a limiting resource for many microorganisms; a strong siderophore-producing PGPR can monopolize this resource and indirectly suppress pathogens." },
    { id:"q-isr-mechanism", topic:"plant-microbe", q:"İndüklenmiş sistemik direnç (ISR) mekanizması nasıl işler?", qEn:"How does the induced systemic resistance (ISR) mechanism work?", opts:["Bitkiyi doğrudan öldürerek","Belirli PGPR'lerle kök etkileşimi, bitkinin bağışıklık sistemini 'uyararak' sonraki patojen saldırılarına karşı daha hızlı tepki vermesini sağlar","Yalnızca toprağı sterilize ederek","Bitkinin büyümesini tamamen durdurarak"], a:1, ex:"ISR, bitkiyi doğrudan koruyan bir mekanizma değil, bitkinin kendi savunma sistemini önceden 'hazırlayarak' gerçek bir tehditle daha hızlı ve etkili mücadele etmesini sağlayan bir 'hazırlık' durumudur.", exEn:"ISR isn't a mechanism that directly protects the plant — it's a 'primed' state that lets the plant's own defense system respond faster and more effectively when a real threat arrives." },
    { id:"q-quorum-sensing-coordination", topic:"plant-microbe", q:"Kuorum algılama, bakterilerin hangi davranışını koordine etmelerine olanak tanır?", qEn:"What behavior does quorum sensing allow bacteria to coordinate?", opts:["Bireysel, birbirinden bağımsız davranışları","Popülasyon yoğunluğu belirli bir eşiğe ulaştığında biyofilm oluşumu gibi kolektif davranışları","Yalnızca üremeyi durdurmayı","Fotosentez yapmayı"], a:1, ex:"Bakteriler, salgıladıkları sinyal moleküllerinin konsantrasyonunu 'algılayarak' yeterli sayıda oldukları anlaşıldığında topluca belirli genleri aktive edebilir (örn. biyofilm oluşumu).", exEn:"By 'sensing' the concentration of the signaling molecules they secrete, bacteria can collectively activate certain genes (e.g. biofilm formation) once they detect sufficient numbers." },
    { id:"q-am-vs-rhizobium-function", topic:"plant-microbe", q:"Arbüsküler mikoriza ile Rhizobium simbiyozu arasındaki temel fonksiyonel fark nedir?", qEn:"What is the key functional difference between arbuscular mycorrhiza and Rhizobium symbiosis?", opts:["İkisi de aynı besini sağlar","AM öncelikle fosfor ve su alımını artırırken, Rhizobium simbiyozu atmosferik azotu sabitler","Rhizobium yalnızca su sağlar","AM yalnızca patojenlere karşı korur"], a:1, ex:"İki simbiyoz farklı besin ihtiyaçlarını hedefler: AM mantarları genişletilmiş hif ağıyla fosfor/su alımını artırırken, Rhizobium doğrudan atmosferik N₂'yi sabitler.", exEn:"The two symbioses target different nutrient needs: AM fungi boost phosphorus/water uptake through an extended hyphal network, while Rhizobium directly fixes atmospheric N₂." },
    { id:"q-exudates-quorum-interaction", topic:"plant-microbe", q:"Kök salgıları, rizosferdeki bakteri popülasyonlarının kuorum algılama davranışını nasıl etkileyebilir?", qEn:"How can root exudates influence the quorum sensing behavior of rhizosphere bacterial populations?", opts:["Hiçbir etkisi yoktur, ilgisiz süreçlerdir","Kök salgılarının sağladığı zengin besin ortamı, bakteri popülasyon yoğunluğunun hızla kuorum algılama eşiğine ulaşmasını kolaylaştırabilir","Kök salgıları kuorum algılamayı her zaman engeller","Kuorum algılama yalnızca patojenlerde görülür"], a:1, ex:"Rizosferdeki bol besin, yüksek bakteri yoğunluğuna yol açabilir; bu da kuorum algılama eşiğine daha hızlı ulaşılmasını ve kolektif davranışların (biyofilm gibi) tetiklenmesini kolaylaştırır.", exEn:"The abundant nutrients in the rhizosphere can drive high bacterial density, which makes reaching the quorum sensing threshold — and triggering collective behaviors like biofilm formation — easier." },
    { id:"q-siderophore-isr-combined", topic:"plant-microbe", q:"Bir PGPR'nin hem siderofor üretimi hem de ISR tetiklemesi, patojenlere karşı nasıl çok yönlü bir savunma sağlar?", qEn:"How does a PGPR producing both siderophores and triggering ISR provide a multi-layered defense against pathogens?", opts:["İkisi birbiriyle çelişir, aynı anda işlemez","Biri patojeni doğrudan kaynak açısından zayıflatırken (demir rekabeti), diğeri bitkinin kendi savunmasını güçlendirir — tamamlayıcı iki mekanizma","İkisi de aynı şeyi yapar, gereksiz tekrardır","Yalnızca biri gerçek bir korumaya yol açar"], a:1, ex:"Siderofor üretimi patojeni doğrudan bir kaynaktan (demir) mahrum bırakırken, ISR bitkinin kendi savunma tepkisini güçlendirir — bu iki mekanizma farklı yollarla aynı hedefe, patojen baskılamaya, katkıda bulunur.", exEn:"Siderophore production directly deprives the pathogen of a resource (iron), while ISR strengthens the plant's own defense response — two mechanisms contributing to the same goal, pathogen suppression, through different routes." },
    { id:"q-mycorrhiza-reciprocity", topic:"plant-microbe", q:"Mikorizal ortaklığın bitkiye sağladığı faydalar karşılığında bitki mantara ne sağlar?", qEn:"In return for the benefits a mycorrhizal partnership provides the plant, what does the plant give the fungus?", opts:["Hiçbir şey, ilişki tek yönlüdür","Fotosentezle ürettiği şekerleri (karbon kaynağı) mantara aktarır","Yalnızca su sağlar","Yalnızca fiziksel barınak sağlar"], a:1, ex:"Mikorizal simbiyoz karşılıklıdır: mantar suyun/besinlerin alımını artırırken, bitki karşılığında fotosentez ürünü şekerleri mantara aktararak onun enerji ihtiyacını karşılar.", exEn:"Mycorrhizal symbiosis is reciprocal: the fungus boosts water/nutrient uptake, while the plant transfers photosynthetic sugars to the fungus in return, meeting its energy needs." },

    // --- applications (15) ---
    { id:"q-bioremediation-role", topic:"applications", q:"Biyoremediasyonda mikroorganizmalar hangi rolü oynar?", qEn:"In bioremediation, what role do microorganisms play?", opts:["Toprağı daha fazla kirletirler","Kirleticileri parçalayarak veya zararsız hale getirerek toprak sağlığının geri kazanılmasına yardımcı olurlar","Kirleticiler üzerinde ölçülebilir bir etkileri yoktur","Yalnızca inorganik kirleticiler üzerinde etkilidirler"], a:1, ex:"Belirli bakteri ve mantarlar organik kirleticileri (örn. hidrokarbonlar) metabolize edebilir veya ağır metalleri daha az zararlı formlara dönüştürebilir.", exEn:"Certain bacteria and fungi can metabolize organic pollutants (e.g. hydrocarbons) or transform heavy metals into less harmful forms." },
    { id:"q-phytoremediation-def", topic:"applications", q:"Fitoremediasyon nedir?", qEn:"What is phytoremediation?", opts:["Bitkilerin yalnızca estetik amaçla kullanılması","Kirletici maddeleri uzaklaştırmak, parçalamak veya sabitlemek için bitkilerin (genellikle kök mikrobiyomlarıyla) kullanılması","Yalnızca sentetik kimyasallarla arıtma","Bitkilerin toprağı kirletmesi"], a:1, ex:"Fitoremediasyon, bitkilerin kirleticileri biriktirme, parçalama veya sabitleme yeteneğinden yararlanır; genellikle kök bölgesindeki mikroorganizmalarla birlikte çalışır.", exEn:"Phytoremediation exploits plants' ability to accumulate, degrade, or stabilize contaminants; it typically works together with root-zone microorganisms." },
    { id:"q-mycoremediation-mechanism", topic:"applications", q:"Mikoremediasyon hangi özelliği sayesinde etkili bir kirlilik giderme yöntemi olabilir?", qEn:"What property allows mycoremediation to be an effective pollution-removal method?", opts:["Mantarların hiçbir özel yeteneği yoktur","Mantarların güçlü enzim sistemleri, petrol türevleri gibi karmaşık kirleticileri parçalayabilir","Mantarlar yalnızca su kirliliğini giderir","Mikoremediasyon yalnızca laboratuvarda çalışır"], a:1, ex:"Bazı mantarlar, lignin gibi karmaşık bileşikleri parçalamak için ürettikleri güçlü enzimleri, yapısal olarak benzer kirleticileri parçalamak için de kullanabilir.", exEn:"Some fungi can repurpose the powerful enzymes they produce to break down complex compounds like lignin to also degrade structurally similar pollutants." },
    { id:"q-biopesticide-vs-biocontrol", topic:"applications", q:"Bir biyopestisit ile bir biyolojik mücadele organizması arasındaki ilişki nedir?", qEn:"What is the relationship between a biopesticide and a biocontrol organism?", opts:["Aynı şeydir, hiçbir fark yoktur","Biyopestisit, bir biyolojik mücadele organizmasından veya onun bileşiklerinden elde edilen, ticari olarak formüle edilmiş üründür","Biyopestisit yalnızca sentetik kimyasaldır","Biyolojik mücadele organizmaları hiçbir zaman ürün haline getirilemez"], a:1, ex:"Biyolojik mücadele organizması canlı bir ajanken, biyopestisit bu ajandan (veya ürettiği bileşiklerden) elde edilen, kullanıma hazır formüle edilmiş bir üründür.", exEn:"A biocontrol organism is a living agent, while a biopesticide is a ready-to-use commercial product formulated from that agent (or its compounds)." },
    { id:"q-biostimulant-vs-biofertilizer", topic:"applications", q:"Bir biyostimülantı bir biyogübreden ayıran temel fark nedir?", qEn:"What is the key difference between a biostimulant and a biofertilizer?", opts:["Aynı şeydir","Biyogübre doğrudan besin sağlarken, biyostimülant besin alımını, stres toleransını veya gelişimi teşvik eder, doğrudan besin sağlamaz","Biyostimülant yalnızca sentetik bir üründür","Biyogübre hiçbir zaman mikroorganizma içermez"], a:1, ex:"Biyogübre besin kaynağı sağlamaya odaklanırken, biyostimülant bitkinin kendi fizyolojik süreçlerini (besin alımı, stres direnci) iyileştirmeye odaklanır.", exEn:"A biofertilizer focuses on providing a nutrient source, while a biostimulant focuses on improving the plant's own physiological processes (nutrient uptake, stress resistance)." },
    { id:"q-inoculant-practical-challenge", topic:"applications", q:"Bir mikrobiyal aşının (inokülant) etkinliği için hangi pratik zorluk önemlidir?", qEn:"What practical challenge matters for a microbial inoculant's effectiveness?", opts:["Hiçbir zorluk yoktur, her zaman etkilidir","Canlı mikroorganizmaların raf ömrü boyunca hayatta kalması ve uygulandığında yerli toprak mikroorganizmalarıyla rekabet edip yerleşebilmesi","Yalnızca maliyet bir sorundur","İnokülantlar hiçbir zaman canlı organizma içermez"], a:1, ex:"Bir inokülantın laboratuvardaki etkinliği, formülasyonun raf ömrü boyunca canlılığı koruyup korumadığına ve tarlada yerli mikrobiyotayla rekabet edip kalıcı olabilmesine bağlıdır.", exEn:"An inoculant's lab effectiveness depends on whether the formulation stays viable over its shelf life, and whether it can compete with native microbiota to establish itself in the field." },
    { id:"q-compost-tea-prep", topic:"applications", q:"Kompost çayı nasıl elde edilir ve amacı nedir?", qEn:"How is compost tea prepared, and what is its purpose?", opts:["Kompostun yakılmasıyla elde edilir","Olgun kompostun suda (bazen havalandırılarak) bekletilmesiyle elde edilen, faydalı mikroorganizma ve çözünür besin içeren bir sıvı uygulamadır","Yalnızca sentetik gübrelerin sulandırılmasıdır","Kompost çayının hiçbir biyolojik içeriği yoktur"], a:1, ex:"Kompost çayı, katı kompostun faydalı mikrobiyal ve besin içeriğinin bir kısmını sıvı forma aktararak, yapraklara veya toprağa daha kolay uygulanabilir hale getirir.", exEn:"Compost tea transfers some of solid compost's beneficial microbial and nutrient content into liquid form, making it easier to apply to leaves or soil." },
    { id:"q-bio-indicators-importance", topic:"applications", q:"Biyolojik toprak sağlığı göstergeleri (mikrobiyal biyokütle, solunum, enzim aktivitesi) neden önemlidir?", qEn:"Why do biological soil health indicators (microbial biomass, respiration, enzyme activity) matter?", opts:["Hiçbir ek bilgi sağlamazlar","Yalnızca kimyasal/fiziksel testlerin yakalayamadığı toprağın biyolojik işlevselliğini değerlendirirler","Yalnızca toprağın rengini ölçerler","Bu göstergeler asla ölçülemez"], a:1, ex:"Bir toprak kimyasal olarak yeterli besine sahip görünse bile, düşük biyolojik aktivite göstergeleri, toprağın işlevsel sağlığında bir sorun olabileceğine işaret edebilir.", exEn:"Even if a soil looks chemically adequate, low biological activity indicators can flag a problem with its functional health." },
    { id:"q-bioremediation-vs-phyto", topic:"applications", q:"Biyoremediasyon ile fitoremediasyon arasındaki ilişki nedir?", qEn:"What is the relationship between bioremediation and phytoremediation?", opts:["Tamamen ayrı, ilgisiz kavramlardır","Fitoremediasyon, biyoremediasyonun bitki (genellikle kök mikrobiyomuyla birlikte) kullanan bir alt türüdür","Biyoremediasyon yalnızca bitkilerle yapılır","Fitoremediasyon hiçbir zaman mikroorganizma içermez"], a:1, ex:"Biyoremediasyon geniş bir kategoridir (mikroorganizma, bitki veya ikisinin birlikte kullanımını kapsar); fitoremediasyon bunun bitki temelli, genellikle kök mikrobiyomuyla desteklenen bir alt kümesidir.", exEn:"Bioremediation is a broad category (covering microorganisms, plants, or both together); phytoremediation is its plant-based subset, usually supported by the root microbiome." },
    { id:"q-biopesticide-formulation-value", topic:"applications", q:"Bir üretici tarlaya doğrudan canlı bir biyolojik mücadele organizması yerine ticari bir biyopestisit ürünü uyguladığında, ne fark yaratır?", qEn:"What difference does it make when a grower applies a commercial biopesticide product instead of a live biocontrol organism directly?", opts:["Hiçbir fark yaratmaz, aynı şeydir","Biyopestisit, standartlaştırılmış formülasyon, dozaj ve raf ömrü sağlayarak uygulamayı daha öngörülebilir hale getirir","Biyopestisit her zaman daha az etkilidir","Canlı organizma uygulamak yasa dışıdır"], a:1, ex:"Ticari formülasyon süreci, etkin bileşeni standartlaştırarak, ham bir kültürün doğrudan uygulanmasına kıyasla daha tutarlı ve öngörülebilir sonuçlar sağlamayı amaçlar.", exEn:"The commercial formulation process standardizes the active ingredient, aiming for more consistent and predictable results than applying a raw culture directly." },
    { id:"q-mycorrhiza-inoculant-success", topic:"applications", q:"Mikorizal mantar inokülantlarının tarlada başarılı olması için hangi koşul önemlidir?", qEn:"What condition matters for mycorrhizal fungal inoculants to succeed in the field?", opts:["Hiçbir koşul gerekmez, her zaman başarılıdır","Toprakta zaten yerli mikorizal popülasyonların düşük olması ve konak bitkinin mikoriza oluşturabilen bir tür olması","İnokülant yalnızca steril toprakta başarısız olur","Mikorizal inokülantlar yalnızca sulu ortamlarda çalışır"], a:1, ex:"Eğer toprakta zaten güçlü bir yerli mikorizal popülasyon varsa, ek inokülasyonun getirisi sınırlı olabilir; başarı ayrıca bitkinin mikoriza oluşturma kapasitesine de bağlıdır.", exEn:"If the soil already has a strong native mycorrhizal population, additional inoculation may offer limited benefit; success also depends on whether the plant is capable of forming mycorrhizae at all." },
    { id:"q-biostimulant-stress-mechanism", topic:"applications", q:"Bir biyostimülantın bitkide stres toleransını artırması ne anlama gelir?", qEn:"What does it mean for a biostimulant to increase a plant's stress tolerance?", opts:["Bitkiyi tüm streslerden tamamen bağışık hale getirir","Bitkinin kuraklık veya tuzluluk gibi streslere karşı fizyolojik tepkisini güçlendirerek zararı azaltabilir","Stres toleransı biyostimülantlarla hiçbir ilgisi yoktur","Yalnızca hastalık direncini etkiler, çevresel stresle ilgisi yoktur"], a:1, ex:"Biyostimülantlar genellikle bitkinin kendi stres-tepki mekanizmalarını (örn. antioksidan üretimi) destekleyerek, tam bağışıklık değil, azaltılmış zarar sağlar.", exEn:"Biostimulants typically support the plant's own stress-response mechanisms (e.g. antioxidant production), reducing damage rather than granting full immunity." },
    { id:"q-compost-tea-vs-solid", topic:"applications", q:"Kompost çayı uygulamasının katı kompost uygulamasına göre bir avantajı nedir?", qEn:"What is an advantage of compost tea application over solid compost application?", opts:["Hiçbir avantajı yoktur","Sıvı formu, yapraklara püskürtme dahil daha hızlı ve esnek uygulama yöntemlerine olanak tanır","Kompost çayı her zaman daha fazla besin içerir","Katı kompost hiçbir zaman uygulanamaz"], a:1, ex:"Sıvı formda olması, kompost çayının hem toprağa hem de doğrudan yaprak yüzeyine (yaprak gübrelemesi gibi) hızlı ve pratik biçimde uygulanmasını mümkün kılar.", exEn:"Being liquid lets compost tea be applied quickly and practically to both soil and directly to leaf surfaces (like a foliar feed)." },
    { id:"q-bio-indicators-feedback-loop", topic:"applications", q:"Biyolojik toprak sağlığı göstergelerinin düzenli izlenmesi, bir üreticiye pratik olarak ne sağlar?", qEn:"What does regularly monitoring biological soil health indicators practically give a grower?", opts:["Hiçbir pratik fayda sağlamaz","Farklı yönetim uygulamalarının (örtü bitkisi, azaltılmış işleme) toprak biyolojisi üzerindeki etkisini zaman içinde takip etme imkanı","Yalnızca bir kerelik bir ölçüm sağlar, tekrar gerekmez","Yalnızca kimyasal gübre ihtiyacını gösterir"], a:1, ex:"Zaman içinde tekrarlanan biyolojik ölçümler, bir uygulamanın (örn. örtü bitkisi eklemenin) toprak biyolojik aktivitesini gerçekten iyileştirip iyileştirmediğini somut olarak göstermeye yardımcı olur.", exEn:"Repeated biological measurements over time help concretely show whether a practice (e.g. adding a cover crop) is actually improving soil biological activity." },
    { id:"q-biofertilizer-vs-biopesticide-purpose", topic:"applications", q:"Biyogübre ile biyopestisit arasındaki temel amaç farkı nedir?", qEn:"What is the core purpose difference between a biofertilizer and a biopesticide?", opts:["Aynı amaca hizmet ederler","Biyogübre bitki besin alımını artırmayı, biyopestisit ise zararlı veya hastalık etmenlerini kontrol etmeyi hedefler","Biyopestisit yalnızca besin sağlar","Biyogübre yalnızca zararlıları öldürür"], a:1, ex:"İki ürün kategorisi farklı birincil amaçlara hizmet eder: biri beslenmeyi destekler, diğeri zararlı organizmaları kontrol eder — ikisi de mikrobiyal kökenli olabilir ama işlevleri farklıdır.", exEn:"The two product categories serve different primary purposes: one supports nutrition, the other controls harmful organisms — both may be microbial in origin, but their functions differ." },

    // --- methods (15) ---
    { id:"q-culture-independent-why", topic:"methods", q:"Metagenomik gibi kültürden bağımsız yöntemler toprak mikrobiyomu araştırmaları için neden önemlidir?", qEn:"Why do culture-independent methods like metagenomics matter for soil microbiome research?", opts:["Çünkü tüm toprak mikropları kolayca kültüre alınabilir","Çünkü çoğu toprak mikroorganizması standart laboratuvar kültür teknikleriyle üretilemez","Çünkü basitçe her alternatiften daha ucuzdur","Çünkü yalnızca mantarları tespit ederler"], a:1, ex:"Çevresel mikropların büyük çoğunluğu standart kültürlemeye direnç gösterir; bu yüzden topluluğun tamamını görmenin tek yolu DNA'yı doğrudan topraktan dizilemektir.", exEn:"The vast majority of environmental microbes resist standard culturing, so sequencing DNA directly from soil is the only way to see the full community." },
    { id:"q-rrna-target", topic:"methods", q:"16S rRNA gen dizileme neyi hedef alır ve neden kullanılır?", qEn:"What does 16S rRNA gene sequencing target, and why is it used?", opts:["Bitki ıslahında kullanılan bir bitki geni","Bir örnekteki taksonları tanımlamak ve sınıflandırmak için kullanılan, korunmuş bir bakteri/arke geni","Yalnızca patojenlerde bulunan bir gen","Yalnızca mantarlara özgü bir belirteç gen"], a:1, ex:"16S rRNA geni neredeyse tüm bakteri ve arkelerde bulunduğu, ama türler arasında yeterince farklılaştığı için evrensel bir tanımlama belirteci olarak işlev görür.", exEn:"Because the 16S rRNA gene is present in nearly all bacteria and archaea but varies enough between species, it works as a universal identification marker." },
    { id:"q-enzyme-activity-indicator", topic:"methods", q:"Toprak biyoteknolojisi çalışmalarında toprak enzim aktivitesi neden bir gösterge olarak kullanılabilir?", qEn:"Why might soil enzyme activity be used as an indicator in soil biotechnology studies?", opts:["Biyolojik bir önemi yoktur","Yalnızca kimin var olduğunu değil, mikrobiyal topluluğun işlevsel ve metabolik aktivitesini de yansıtır","Yalnızca toprak bünyesini ölçer","Mikrobiyal süreçlerle ilgisi yoktur"], a:1, ex:"Enzim aktivitesi, mikrobiyal topluluğun fiilen ne yaptığını (örn. organik maddeyi parçalamak) gösterir ve 16S dizileme gibi 'kim var' verisini tamamlar.", exEn:"Enzyme activity shows what the microbial community is actually doing (e.g. breaking down organic matter), complementing who-is-there data like 16S sequencing." },
    { id:"q-pcr-basic-function", topic:"methods", q:"PCR tekniği temel olarak ne yapar?", qEn:"What does the PCR technique fundamentally do?", opts:["Mikroorganizmaları öldürür","Belirli bir DNA dizisinin laboratuvarda milyonlarca kopyasını üretir","Toprağın pH'ını ölçer","Yalnızca canlı hücreleri sayar"], a:1, ex:"PCR, hedeflenen kısa bir DNA dizisini tekrarlanan ısıtma-soğutma döngüleriyle katlanarak çoğaltır; bu da onu son derece az miktardaki DNA'yı bile tespit edilebilir hale getiren güçlü bir araç yapar.", exEn:"PCR exponentially amplifies a short target DNA sequence through repeated heating-cooling cycles, making it a powerful tool for detecting even tiny amounts of DNA." },
    { id:"q-fish-visualization", topic:"methods", q:"FISH tekniği neyi mümkün kılar?", qEn:"What does the FISH technique make possible?", opts:["Mikroorganizmaların kültürde üretilmesini","Floresan işaretli problarla belirli mikroorganizma gruplarının örnek içinde yerinde görselleştirilmesini","Toprağın kimyasal analizini","Yalnızca DNA dizileme"], a:1, ex:"FISH, floresan işaretli DNA problarının hedef mikroorganizmaların rRNA'sına bağlanmasını sağlayarak, onların örnekteki konumunu ve varlığını doğrudan görselleştirir.", exEn:"FISH lets fluorescently labeled DNA probes bind to target microorganisms' rRNA, directly visualizing their presence and location within a sample." },
    { id:"q-plfa-community-info", topic:"methods", q:"PLFA analizi mikrobiyal topluluk hakkında ne tür bir bilgi sağlar?", qEn:"What kind of information does PLFA analysis provide about a microbial community?", opts:["Yalnızca tek bir türün kimliğini","Topluluğun genel yapısını (örn. bakteri/mantar oranı), canlı hücre zarı yağ asitlerine dayanarak","Toprağın nem içeriğini","Yalnızca DNA dizisini"], a:1, ex:"Farklı mikroorganizma grupları karakteristik yağ asidi profillerine sahiptir; bu profillerin analizi, canlı biyokütlenin genel topluluk yapısını yansıtır.", exEn:"Different microbial groups have characteristic fatty acid profiles; analyzing these reflects the overall community structure of the living biomass." },
    { id:"q-metatranscriptomics-vs-metagenomics", topic:"methods", q:"Metatranskriptomik, metagenomikten hangi temel farkla ayrılır?", qEn:"What is the key difference between metatranscriptomics and metagenomics?", opts:["Aynı şeydir, farklı isimdir","Metagenomik 'kimin var olduğunu' (DNA), metatranskriptomik ise 'kimin şu an ne yaptığını' (aktif ifade edilen RNA) gösterir","Metatranskriptomik yalnızca ölü hücreleri inceler","Metagenomik yalnızca canlı hücreleri inceler"], a:1, ex:"DNA bir organizmanın genetik potansiyelini gösterirken, RNA (transkript) o anda hangi genlerin aktif olarak kullanıldığını gösterir — bu da topluluğun anlık işlevsel durumuna dair çok daha dinamik bir görüntü sunar.", exEn:"DNA shows an organism's genetic potential, while RNA (transcripts) show which genes are actively in use at that moment — offering a far more dynamic picture of the community's real-time functional state." },
    { id:"q-qpcr-additional-measure", topic:"methods", q:"qPCR, standart PCR'a kıyasla ek olarak neyi ölçebilir?", qEn:"What can qPCR additionally measure compared to standard PCR?", opts:["Hiçbir ek bilgi sağlamaz","Hedef DNA dizisinin örnekteki başlangıç miktarını (bolluğunu) nicel olarak ölçebilir","Yalnızca DNA'nın rengini ölçer","Yalnızca toprağın sıcaklığını ölçer"], a:1, ex:"qPCR, çoğaltma sürecini gerçek zamanlı izleyerek, örnekte başlangıçta ne kadar hedef DNA bulunduğunu nicel olarak hesaplamayı mümkün kılar.", exEn:"By monitoring the amplification process in real time, qPCR makes it possible to quantitatively calculate how much target DNA was present in the sample to begin with." },
    { id:"q-mpn-approach", topic:"methods", q:"En Muhtemel Sayı (EMS) yöntemi hangi temel yaklaşıma dayanır?", qEn:"What basic approach does the Most Probable Number (MPN) method rely on?", opts:["DNA dizilemeye","Ardışık seyreltmeler ve gözlemlenen büyümeye dayalı istatistiksel tahmine","Floresan mikroskopiye","Kütle spektrometrisine"], a:1, ex:"EMS, bir örneği art arda seyrelterek, hangi seyreltme düzeylerinde büyüme gözlemlendiğine bakarak, istatistiksel tablolar aracılığıyla başlangıç yoğunluğunu tahmin eden klasik bir yöntemdir.", exEn:"MPN is a classic method that serially dilutes a sample and, based on which dilution levels show growth, estimates the original density using statistical tables." },
    { id:"q-dgge-fingerprint", topic:"methods", q:"DGGE tekniği bir mikrobiyal topluluk hakkında ne sağlar?", qEn:"What does the DGGE technique provide about a microbial community?", opts:["Topluluğun tam genomik dizisini","PCR ile çoğaltılmış DNA parçalarının dizi farklılıklarına göre ayrılmasıyla oluşan genel bir topluluk 'parmak izi'ni","Yalnızca tek bir organizmanın kimliğini","Toprağın fiziksel yapısını"], a:1, ex:"DGGE, farklı dizilere sahip DNA parçalarının jelde farklı noktalarda durmasını sağlayarak, sekanslama olmadan bile topluluklar arasında görsel karşılaştırma yapılmasına olanak tanır.", exEn:"DGGE makes DNA fragments with different sequences stop at different points on a gel, allowing visual comparison between communities even without sequencing." },
    { id:"q-pcr-foundation-methods", topic:"methods", q:"PCR'ın, qPCR ve DGGE gibi diğer birçok yöntemin temelini oluşturması ne anlama gelir?", qEn:"What does it mean that PCR underlies many other methods like qPCR and DGGE?", opts:["Bu yöntemlerin PCR ile hiçbir ilgisi yoktur","Bu yöntemlerin çoğu, analiz için yeterli DNA materyali elde etmek amacıyla ilk adım olarak PCR ile çoğaltma kullanır","PCR yalnızca tek başına kullanılabilir, başka yöntemle birleştirilemez","PCR yalnızca hayvan örneklerinde çalışır"], a:1, ex:"Çevresel örneklerdeki DNA miktarı genellikle doğrudan analiz için yetersizdir; PCR bu materyali çoğaltarak sonraki analiz adımlarını (dizileme, jel ayrımı vb.) mümkün kılar.", exEn:"The amount of DNA in environmental samples is usually too small for direct analysis; PCR amplifies this material to enable subsequent analysis steps (sequencing, gel separation, etc.)." },
    { id:"q-culture-based-limitation", topic:"methods", q:"En Muhtemel Sayı (EMS) gibi kültüre dayalı yöntemler, metagenomik gibi kültürden bağımsız yöntemlerle karşılaştırıldığında hangi temel sınırlamaya sahiptir?", qEn:"What key limitation do culture-based methods like MPN have compared to culture-independent methods like metagenomics?", opts:["Hiçbir sınırlaması yoktur","Yalnızca laboratuvar koşullarında kültürlenebilen mikroorganizmaları tespit edebilir, bu da toprak mikroplarının büyük çoğunluğunu gözden kaçırır","EMS her zaman daha doğrudur","Kültürden bağımsız yöntemler daha eskidir"], a:1, ex:"EMS gibi yöntemler yalnızca seçilen kültür ortamında büyüyebilen organizmaları sayabilir; toprak mikroplarının büyük çoğunluğu standart kültür koşullarında üretilemediğinden bu ciddi bir kör nokta yaratır.", exEn:"Methods like MPN can only count organisms able to grow on the chosen culture medium; since most soil microbes can't be grown under standard culture conditions, this creates a serious blind spot." },
    { id:"q-fish-vs-sequencing", topic:"methods", q:"FISH tekniği ile DNA dizileme arasındaki temel fark nedir?", qEn:"What is the key difference between the FISH technique and DNA sequencing?", opts:["Aynı bilgiyi sağlarlar","FISH, hedef organizmaların örnek içindeki uzamsal konumunu doğrudan görselleştirirken, dizileme yalnızca hangi dizilerin var olduğunu listeler, konum bilgisi vermez","Dizileme konum bilgisi verirken FISH vermez","FISH yalnızca bitkilerde kullanılır"], a:1, ex:"FISH'in benzersiz avantajı, hedef mikroorganizmaların örnekteki tam konumunu (örn. kök yüzeyinde mi, toprak parçacığında mı) görsel olarak göstermesidir; standart dizileme bu uzamsal bilgiyi kaybeder.", exEn:"FISH's unique advantage is visually showing exactly where target microorganisms are located in a sample (e.g. on a root surface vs. a soil particle) — standard sequencing loses this spatial information." },
    { id:"q-metatranscriptomics-application", topic:"methods", q:"Bir araştırmacı, bir toprağın yalnızca hangi mikropları barındırdığını değil, o mikropların hangi işlevleri o anda aktif olarak yürüttüğünü bilmek istiyorsa hangi yöntemi tercih etmelidir?", qEn:"If a researcher wants to know not just which microbes a soil contains, but which functions those microbes are actively carrying out right now, which method should they choose?", opts:["Metagenomik, çünkü yalnızca DNA yeterlidir","Metatranskriptomik, çünkü aktif olarak ifade edilen genleri (RNA) ölçer","16S rRNA dizileme, çünkü yalnızca taksonomik kimlik verir","PLFA analizi, çünkü yalnızca yağ asitlerini ölçer"], a:1, ex:"Metagenomik genetik potansiyeli (kim ne yapabilir) gösterirken, metatranskriptomik o anda gerçekten ne yapıldığını (aktif gen ifadesi) gösterir.", exEn:"Metagenomics shows genetic potential (who could do what), while metatranscriptomics shows what's actually being done right now (active gene expression)." },
    { id:"q-qpcr-vs-mpn-advantage", topic:"methods", q:"qPCR, En Muhtemel Sayı (EMS) yöntemine kıyasla mikroorganizma bolluğunu tahmin etmede genellikle hangi avantajı sunar?", qEn:"What advantage does qPCR generally offer over the MPN method for estimating microbial abundance?", opts:["Hiçbir avantajı yoktur, ikisi aynı doğruluktadır","Kültürlemeye ihtiyaç duymadan, DNA miktarına dayalı olarak daha hızlı ve genellikle daha hassas bir nicel tahmin sağlar","qPCR yalnızca canlı hücreleri sayabilir, EMS ölü hücreleri de sayar","EMS her zaman daha ucuzdur ve tercih edilir"], a:1, ex:"qPCR, kültürleme gerektiren ve günler sürebilen EMS'nin aksine, DNA miktarını doğrudan ölçerek daha hızlı sonuç verir ve kültürlenemeyen organizmaları da tespit edebilir.", exEn:"Unlike MPN, which requires culturing and can take days, qPCR gives faster results by directly measuring DNA quantity, and can also detect unculturable organisms." }
  ]
};
